import org.junit.Test;
import static org.junit.Assert.*;

public class DBAppTest {

    @Test
    public void testInit() {
        DBApp dbApp = new DBApp();
        assertNotNull(dbApp);
        assertEquals(0, dbApp.getMyTables().size());
        assertNotNull(dbApp.getCsvReader());
        assertNotNull(dbApp.getCsvWriter());
    }

    @Test
    public void testCreateTable() throws DBAppException {
        DBApp dbApp = new DBApp();
        dbApp.createTable("my_table", "column1", null, null, null);
        assertNotNull(dbApp.getMyTables().size());
        assertEquals(1, dbApp.getMyTables().size());
        assertTrue(!dbApp.getMyTables().contains("my_table"));
    }

    @Test
    public void testInsertIntoTable() throws DBAppException {
        DBApp dbApp = new DBApp();
        dbApp.createTable("my_table", "column1", null, null, null);
        Hashtable<String, Object> htblColNameValue = new Hashtable<>();
        htblColNameValue.put("value1", 1L);
        dbApp.insertIntoTable("my_table", htblColNameValue);
        assertTrue(!dbApp.getMyTables().contains("my_table"));
    }

    @Test
    public void testUpdateTable() throws DBAppException {
        DBApp dbApp = new DBApp();
        String strTableName = "my_table";
        Hashtable<String, Object> htblColNameValue = new Hashtable<>();
        dbApp.createTable(strTableName, null, null, null, null);
        dbApp.updateTable(strTableName, null, htblColNameValue);
        assertFalse(dbApp.getMyTables().contains(strTableName));
    }

    @Test
    public void testDeleteFromTable() throws DBAppException {
        DBApp dbApp = new DBApp();
        String strTableName = "my_table";
        Hashtable<String, Object> htblColNameValue = new Hashtable<>();
        dbApp.createTable(strTableName, null, null, null, null);
        dbApp.deleteFromTable(strTableName, htblColNameValue);
        assertTrue(!dbApp.getMyTables().contains(strTableName));
    }

    @Test
    public void testSelectFromTable() {
        DBApp dbApp = new DBApp();
        String strTableName = "my_table";
        Hashtable<String, Object> htblColNameValue = new Hashtable<>();
        dbApp.createTable(strTableName, null, null, null, null);
        Hashtable<String, SQLTerm> sqlTerms = new Hashtable<>();
        sqlTerms.put(new SQLTerm("row1"), new SQLTerm(1L));
        sqlTerms.put(new SQLTerm("row2"), new SQLTerm(2L));
        dbApp.insertIntoTable(strTableName, htblColNameValue);
        assertTrue(!dbApp.getMyTables().contains(strTableName));
        Hashtable<String, Object> result = dbApp.selectFromTable(sqlTerms);
        assertEquals(1, result.size());
    }
}
